'use strict';
// All sound is generated by the browser (no audio files): short effects and a slow, moody music loop.
const Sfx = (() => {
  let ac = null, master = null, mus = null, muted = false, last = {}, timer = null, step = 0, nextT = 0, intense = false, playing = false;
  try { muted = localStorage.getItem('lastlanterns.muted') === '1'; } catch (e) { /* ignore */ }

  function init() {
    if (ac) { if (ac.state === 'suspended') ac.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext; if (!AC) return;
    ac = new AC(); master = ac.createGain(); master.gain.value = muted ? 0 : 0.8; master.connect(ac.destination);
    mus = ac.createGain(); mus.gain.value = 0; mus.connect(master);
    timer = setInterval(schedule, 200);
  }
  function tone(f, dur, type, gain, slide, delay, out) {
    const t = ac.currentTime + (delay || 0), o = ac.createOscillator(), g = ac.createGain();
    o.type = type || 'sine'; o.frequency.setValueAtTime(f, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, f * slide), t + dur);
    g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(gain, t + 0.008); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(out || master); o.start(t); o.stop(t + dur + 0.03);
  }
  function noise(dur, gain, cut) {
    const n = ac.sampleRate * dur | 0, b = ac.createBuffer(1, n, ac.sampleRate), d = b.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n);
    const s = ac.createBufferSource(), f = ac.createBiquadFilter(), g = ac.createGain();
    s.buffer = b; f.type = 'lowpass'; f.frequency.value = cut; g.gain.value = gain; s.connect(f); f.connect(g); g.connect(master); s.start();
  }
  const GAP = { kill: 55, gem: 45, boom: 110, zap: 80, hurt: 220 };
  const SOUNDS = {
    kill: () => tone(170 + Math.random() * 90, 0.06, 'triangle', 0.05, 0.5),
    gem: () => tone(880 + Math.random() * 260, 0.05, 'sine', 0.035),
    boom: () => { noise(0.28, 0.16, 650); tone(95, 0.28, 'sine', 0.2, 0.4); },
    zap: () => tone(1300, 0.08, 'sawtooth', 0.035, 0.3),
    hurt: () => tone(150, 0.16, 'square', 0.1, 0.5),
    pick: () => { tone(660, 0.08, 'triangle', 0.1); tone(990, 0.12, 'triangle', 0.1, 0, 0.07); },
    level: () => [523, 659, 784, 1046].forEach((f, i) => tone(f, 0.16, 'triangle', 0.1, 0, i * 0.08)),
    evo: () => [392, 523, 659, 784, 1046, 1318].forEach((f, i) => tone(f, 0.3, 'sawtooth', 0.06, 0, i * 0.07)),
    skill: () => tone(380, 0.22, 'triangle', 0.12, 2.2),
    ult: () => { tone(180, 0.7, 'sawtooth', 0.11, 4); noise(0.6, 0.1, 1800); },
    boss: () => { tone(55, 1.8, 'sawtooth', 0.2, 0.7); tone(82, 1.8, 'sawtooth', 0.12, 0.7, 0.1); },
    down: () => [440, 330, 247, 165].forEach((f, i) => tone(f, 0.25, 'triangle', 0.12, 0, i * 0.14)),
    win: () => [523, 659, 784, 1046, 784, 1046, 1318].forEach((f, i) => tone(f, 0.35, 'triangle', 0.11, 0, i * 0.13)),
    lose: () => [330, 294, 247, 196, 147].forEach((f, i) => tone(f, 0.5, 'sine', 0.13, 0, i * 0.22)),
    shrine: () => [659, 880, 1318].forEach((f, i) => tone(f, 0.5, 'sine', 0.09, 0, i * 0.1)),
  };
  function play(name) {
    if (!ac || muted || !SOUNDS[name]) return;
    const now = performance.now(); if (now - (last[name] || 0) < (GAP[name] || 0)) return; last[name] = now;
    try { SOUNDS[name](); } catch (e) { /* audio hiccup: ignore */ }
  }
  // music: four slow chords with a plucked pattern on top; faster and heavier during a boss
  const CH = [[220, 261.6, 329.6], [174.6, 220, 261.6], [130.8, 196, 261.6], [196, 246.9, 293.7]];
  function schedule() {
    if (!ac || !playing) return;
    if (nextT < ac.currentTime) nextT = ac.currentTime + 0.05;
    while (nextT < ac.currentTime + 0.5) {
      const beat = intense ? 0.25 : 0.5, c = CH[(step >> 3) & 3], t = nextT - ac.currentTime;
      if (step % 8 === 0) for (const f of c) { tone(f / 2, beat * 8.4, 'triangle', 0.05, 0, t, mus); tone(f / 2 * 1.005, beat * 8.4, 'sine', 0.04, 0, t, mus); }
      tone(c[[0, 2, 1, 2, 0, 1, 2, 1][step % 8]] * 2, beat * 1.6, 'sine', 0.045, 0, t, mus);
      if (intense && step % 2 === 0) tone(c[0] / 4, 0.2, 'sawtooth', 0.07, 0.6, t, mus);
      step++; nextT += beat;
    }
  }
  function music(on, boss) { intense = !!boss; if (!ac || on === playing) return; playing = on; mus.gain.linearRampToValueAtTime(on ? 0.9 : 0, ac.currentTime + 0.8); }
  function toggle() { muted = !muted; try { localStorage.setItem('lastlanterns.muted', muted ? '1' : '0'); } catch (e) { /* ignore */ } if (master) master.gain.value = muted ? 0 : 0.8; return muted; }
  return { init, play, music, toggle, get muted() { return muted; } };
})();
